entries[13503] = { ["name"] = "Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2 Stärke\n+2 Beweglichkeit\n+2 Intelligenz\n+2 Ausdauer\n+ 2 Vielseitigkeit\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Scherbenwelt\n(50)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[13505] = { ["name"] = "Runenklinge von Baron Totenschwur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nZweihändig Schwert\n6 - 11 Schaden Geschwindigkeit 3.60\n(2.4 Schaden pro Sekunde)\n+3 Stärke\n+5 Ausdauer\n+ 7 Vielseitigkeit\nHaltbarkeit 120 / 120\nAnlegen: Erhöht die Geschwindigkeit um 2 und regeneriert alle 5 Sek. 0 Gesundheit.\nVerkaufspreis:" }
entries[13506] = { ["name"] = "Trank der Versteinerung", ["text"] = "Benutzen: Ihr werdet zu Stein und absorbiert 3438 Schaden aus jeglicher Schadensquelle, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen oder Zauber wirken. Hält 30 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[13507] = { ["name"] = "Klippenbehüter Langhorns Bericht", ["text"] = "Questgegenstand\nEinzigartig\n<Zum Lesen rechtsklicken>" }
entries[13508] = { ["name"] = "Auge von Arachnida", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört das Auge von Kilrogg und bindet Eure Sicht daran. Das Auge ist getarnt und bewegt sich schnell, ist sehr sehr verwundbar. (1 Min Abklingzeit)\n3 Aufladungen\nVerkaufspreis:" }
entries[13509] = { ["name"] = "Klammer der Voraussicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kontert das Zauberwirken des Gegners und verhindert 10 Sek. lang, dass ein Zauber dieser Art gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung. Es besteht die Chance eines Fehlschlags, wenn das Ziel über Stufe 49 ist. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[13510] = { ["name"] = "Fläschchen der Titanen", ["text"] = "Benutzen: Erhöht die maximale Gesundheit des Spielers 1 Stunde lang um 228 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[13511] = { ["name"] = "Fläschchen der destillierten Weisheit", ["text"] = "Benutzen: Erhöht die Intelligenz 1 Stunde lang um 28 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[13512] = { ["name"] = "Fläschchen der obersten Macht", ["text"] = "Benutzen: Erhöht die Zaubermacht 1 Stunde lang um 29 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[13514] = { ["name"] = "Wehklage der Banshee", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verringert die Trefferchance eines Gegners 12 Sek. lang um 10%. Es besteht die Chance, dass der Effekt gegen Ziele über Stufe 49 nicht wirkt. (1 Min Abklingzeit)\n3 Aufladungen\nVerkaufspreis:" }
entries[13515] = { ["name"] = "Ramsteins Blitzbolzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 5.\nBenutzen: Setzt die Macht des Blitzschlags ein, um allen Gegnern um Euch herum ( 1 * 133 ) Naturschaden zuzufügen. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[13517] = { ["name"] = "Rezept: Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Alchemistensteins.\nBenötigt Alchemie der Scherbenwelt\n(50)\nBenötigt Die Sha'tar\n- Respektvoll\nVerkaufspreis:\nAlchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2 Stärke\n+2 Beweglichkeit\n+2 Intelligenz\n+2 Ausdauer\n+ 2 Vielseitigkeit\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Scherbenwelt\n(50)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Stein der Weisen , Erdsturmdiamant , Himmelsfeuerdiamant , Teufelslotus (2), Urmacht (5)\nOptionale Reagenzien: [] (#31)" }
